<?php require 'includes/functions.php';$u=guard();$title='My profile';require 'includes/header.php';?><section class="section narrow"><div class="eyebrow">YOUR ACCOUNT</div><h1>My profile</h1><p><?=e($u['email'])?> · <?=e(ucfirst($u['role']))?></p><form class="panel form-grid" method="post" action="<?=url('actions/profile-actions.php')?>"><?=csrf()?><?php input('Name / Organisation','name','text',$u['name'],'maxlength="100"');input('Phone','phone','tel',$u['phone'],'maxlength="20" pattern="[0-9+ ()-]{7,20}"');input('City','city','text',$u['city'],'maxlength="100"');?><label>Address<textarea name="address" required maxlength="500"><?=e($u['address'])?></textarea></label><h3 class="span2">Change password (optional)</h3><label>Current password<input type="password" name="current_password" autocomplete="current-password"></label><label>New password<input type="password" name="new_password" minlength="8" autocomplete="new-password"></label><button class="button span2">Save profile</button></form></section><?php require 'includes/footer.php';?>